// THRESHOLD ALERT SYSTEM
// ═══════════════════════════════════════════════════════════════

const KPI_META = {
  kpiTotalLeads: { label: 'סה"כ לידים' },
  kpiNewLeads:   { label: 'לידים חדשים' },
  kpiFH:         { label: 'Full House' },
  kpiIH:         { label: 'In House' },
  kpiKR:         { label: 'כרטיסיות' },
  kpiExp:        { label: 'פוגים השבוע' },
};
const ALERT_COOLDOWN = 24 * 60 * 60 * 1000; // 24 hours

function getThresholds() {
  try { return JSON.parse(localStorage.getItem('kpi_thresholds') || '{}'); } catch { return {}; }
}
function saveThresholds(t) { localStorage.setItem('kpi_thresholds', JSON.stringify(t)); }

function getEmailJSCfg() {
  try { return JSON.parse(localStorage.getItem('emailjs_config') || 'null'); } catch { return null; }
}

function initEmailJS() {
  const cfg = getEmailJSCfg();
  if (cfg && cfg.publicKey && window.emailjs) {
    emailjs.init(cfg.publicKey);
  }
}

async function sendAlertEmail(kpiId, value, thresholdType, thresholdValue, toEmail) {
  const cfg = getEmailJSCfg();
  if (!cfg || !cfg.publicKey) { openEmailJSModal(); return; }
  const meta = KPI_META[kpiId] || { label: kpiId };
  const typeLabel = thresholdType === 'lower' ? `ירד מתחת ל-${thresholdValue}` : `עלה מעל ל-${thresholdValue}`;
  try {
    await emailjs.send(cfg.serviceId, cfg.templateId, {
      kpi_name: meta.label,
      current_value: String(value),
      threshold_type: typeLabel,
      threshold_value: String(thresholdValue),
      to_email: toEmail,
      dashboard_url: window.location.href,
    });
    console.log(`📧 התראה נשלחה: ${meta.label} = ${value} (${typeLabel})`);
  } catch(e) {
    console.error('EmailJS error:', e);
  }
}

function checkThresholds(kpiId, value) {
  const t = getThresholds();
  const cfg = t[kpiId];
  if (!cfg || !cfg.enabled) return;
  const num = Number(value);
  if (isNaN(num)) return;

  // Check cooldown
  const ck = `alert_last_${kpiId}`;
  if (Date.now() - Number(localStorage.getItem(ck) || 0) < ALERT_COOLDOWN) return;

  const email = cfg.email || 'arye.glikman@gmail.com';
  let breached = false;

  if (cfg.lower !== '' && cfg.lower !== null && cfg.lower !== undefined && num < Number(cfg.lower)) {
    sendAlertEmail(kpiId, num, 'lower', cfg.lower, email);
    breached = true;
  } else if (cfg.upper !== '' && cfg.upper !== null && cfg.upper !== undefined && num > Number(cfg.upper)) {
    sendAlertEmail(kpiId, num, 'upper', cfg.upper, email);
    breached = true;
  }

  if (breached) {
    localStorage.setItem(ck, String(Date.now()));
    updateThresholdDot(kpiId, 'breached');
  }
}

function checkAllThresholds() {
  Object.keys(KPI_META).forEach(kpiId => {
    const el = document.getElementById(kpiId);
    if (!el) return;
    const raw = el.textContent.replace(/[^\d]/g, '');
    if (raw) checkThresholds(kpiId, parseInt(raw, 10));
  });
}

function renderThresholdDots() {
  const t = getThresholds();
  Object.keys(KPI_META).forEach(kpiId => {
    const el = document.getElementById(kpiId);
    const card = el && el.closest('.kpi-card');
    const dot = card && card.querySelector('.threshold-dot');
    if (!dot) return;
    const cfg = t[kpiId];
    const hasThreshold = cfg && cfg.enabled && (cfg.lower !== '' || cfg.upper !== '');
    dot.className = 'threshold-dot' + (hasThreshold ? ' active' : '');
    dot.title = hasThreshold
      ? `התראה: ${cfg.lower !== '' ? '↓' + cfg.lower + ' ' : ''}${cfg.upper !== '' ? '↑' + cfg.upper : ''}`
      : '';
  });
}

function updateThresholdDot(kpiId, state) {
  const el = document.getElementById(kpiId);
  const card = el && el.closest('.kpi-card');
  const dot = card && card.querySelector('.threshold-dot');
  if (dot) dot.className = `threshold-dot ${state}`;
}

// ── Modal: per-tile threshold settings ──────────────────────
let _activeKpiId = null;

function openThresholdModal(kpiId) {
  _activeKpiId = kpiId;
  const meta = KPI_META[kpiId] || {};
  document.getElementById('tmodalTitle').textContent = `🔔 התראה: ${meta.label || kpiId}`;
  const cfg = (getThresholds()[kpiId]) || { lower: '', upper: '', email: 'arye.glikman@gmail.com', enabled: true };
  document.getElementById('tLower').value   = cfg.lower ?? '';
  document.getElementById('tUpper').value   = cfg.upper ?? '';
  document.getElementById('tEmail').value   = cfg.email || 'arye.glikman@gmail.com';
  document.getElementById('tEnabled').checked = cfg.enabled !== false;
  document.getElementById('thresholdOverlay').classList.add('open');
  document.getElementById('thresholdModal').classList.add('open');
}
function closeThresholdModal() {
  document.getElementById('thresholdOverlay').classList.remove('open');
  document.getElementById('thresholdModal').classList.remove('open');
  _activeKpiId = null;
}
function saveThresholdFromModal() {
  if (!_activeKpiId) return;
  const t = getThresholds();
  t[_activeKpiId] = {
    lower:   document.getElementById('tLower').value.trim(),
    upper:   document.getElementById('tUpper').value.trim(),
    email:   document.getElementById('tEmail').value.trim(),
    enabled: document.getElementById('tEnabled').checked,
  };
  saveThresholds(t);
  renderThresholdDots();
  closeThresholdModal();
}
function clearThreshold() {
  if (!_activeKpiId) return;
  const t = getThresholds();
  delete t[_activeKpiId];
  saveThresholds(t);
  localStorage.removeItem(`alert_last_${_activeKpiId}`);
  renderThresholdDots();
  closeThresholdModal();
}

// ── Modal: EmailJS config ────────────────────────────────────
function openEmailJSModal() {
  const cfg = getEmailJSCfg();
  document.getElementById('ejsPublicKey').value  = cfg?.publicKey  || '';
  document.getElementById('ejsServiceId').value  = cfg?.serviceId  || '';
  document.getElementById('ejsTemplateId').value = cfg?.templateId || '';
  document.getElementById('emailjsOverlay').classList.add('open');
  document.getElementById('emailjsModal').classList.add('open');
}
function closeEmailJSModal() {
  document.getElementById('emailjsOverlay').classList.remove('open');
  document.getElementById('emailjsModal').classList.remove('open');
}
function saveEmailJSConfig() {
  const cfg = {
    publicKey:  document.getElementById('ejsPublicKey').value.trim(),
    serviceId:  document.getElementById('ejsServiceId').value.trim(),
    templateId: document.getElementById('ejsTemplateId').value.trim(),
  };
  if (!cfg.publicKey || !cfg.serviceId || !cfg.templateId) { alert('יש למלא את כל השדות'); return; }
  localStorage.setItem('emailjs_config', JSON.stringify(cfg));
  if (window.emailjs) emailjs.init(cfg.publicKey);
  closeEmailJSModal();
  alert('✅ הגדרות EmailJS נשמרו');
}
async function testEmailJS() {
  const cfg = getEmailJSCfg();
  if (!cfg) { alert('יש לשמור הגדרות EmailJS קודם'); return; }
  if (window.emailjs) emailjs.init(cfg.publicKey);
  try {
    await emailjs.send(cfg.serviceId, cfg.templateId, {
      kpi_name: 'סה"כ לידים (בדיקה)', current_value: '42',
      threshold_type: 'עלה מעל ל-40', threshold_value: '40',
      to_email: 'arye.glikman@gmail.com', dashboard_url: window.location.href,
    });
    alert('✅ מייל בדיקה נשלח לarye.glikman@gmail.com');
  } catch(e) { alert('❌ שגיאה: ' + (e?.text || JSON.stringify(e))); }
}

// ── Inject settings UI into each KPI tile ───────────────────
function initThresholdUI() {
  initEmailJS();
  Object.keys(KPI_META).forEach(kpiId => {
    const el = document.getElementById(kpiId);
    const card = el && el.closest('.kpi-card');
    if (!card) return;
    if (!card.querySelector('.kpi-settings-btn')) {
      const btn = document.createElement('button');
      btn.className = 'kpi-settings-btn';
      btn.textContent = '⚙';
      btn.title = 'הגדר התראת סף';
      btn.addEventListener('click', e => { e.stopPropagation(); openThresholdModal(kpiId); });
      card.appendChild(btn);
    }
    if (!card.querySelector('.threshold-dot')) {
      const dot = document.createElement('div');
      dot.className = 'threshold-dot';
      card.appendChild(dot);
    }
  });
  renderThresholdDots();
}

