async function refreshDashboard() {
  const btn = document.getElementById('refreshBtn');
  if (btn) { btn.disabled = true; btn.textContent = '⟳ מרענן...'; }
  await Promise.all([loadScallaData(), loadStudioData()]);
  if (btn) { btn.disabled = false; btn.textContent = '🔄 רענן נתונים'; }
  checkAllThresholds();
}

// Initialize
(async function init() {
  // Set up threshold UI (gear buttons + dots on each KPI tile)
  initThresholdUI();
  // Start data loading in parallel
  const dataPromise = Promise.all([loadScallaData(), loadStudioData()]);
  // Render marketing tab (static data, needs Chart.js)
  if (typeof Chart !== 'undefined') {
    renderMarketingTab();
  } else {
    window.addEventListener('load', renderMarketingTab);
  }
  await dataPromise;
  // Check all thresholds after data is loaded
  checkAllThresholds();
})();

